from pathlib import Path
from html import escape
import re,hashlib
root=Path(__file__).resolve().parents[2]
p=root/'chapters/ch25.html'; original=p.read_text()
assert hashlib.sha256(p.read_bytes()).hexdigest()=='9c9ed3fb96af6aaf96fc5cbe58b3d1ab7f58313573d645a9eb19238390c75880', 'Concurrent chapter modification'
figs=re.findall(r'<figure class="deck">[\s\S]*?</figure>',original)
assert len(figs)==6
# Only local labels/geometry: preserve all original frames and accessibility IDs.
figs[1]=figs[1].replace('fixed 0.2s/run: 56 / 0.2 = 280/s; burst &gt;= 35.7s','fixed 0.2s/run: ceil(10,000 / 56) x 0.2 = 35.8s')
figs[1]=figs[1].replace('at least 10000 divided by 280, about 35.7 seconds','179 rounds of 0.2 seconds, or 35.8 seconds')
figs[1]=figs[1].replace('至少排 35.7 秒','需 179 轮，也就是至少 35.8 秒').replace('take at least 35.7 s','need 179 rounds, taking at least 35.8 s')
figs[3]=figs[3].replace('inspection / cache refresh; future cursor only','inspection / cache refresh; live cursor only')
figs[3]=figs[3].replace('catch-up: persist 1,200; same claim + retry path','catch-up: page 1,200; same claim + retry path')
figs[3]=figs[3].replace('materializes all 1200 occurrences in Schedule DB','materializes the 1200 occurrences in bounded pages in Schedule DB')
figs[3]=figs[3].replace('1,200 次先落成持久积压','1,200 次分有界页落成持久积压').replace('persist all 1,200 then','persist all 1,200 in bounded pages, then')
